// 변수 정의
$primary-color: #3498db;
$spacing: 16px;
$border-radius: 4px;

// 믹스인 정의
@mixin flex-center {
  display: flex;
  justify-content: center;
  align-items: center;
}

// 중첩 규칙
.card {
  padding: $spacing;
  border-radius: $border-radius;
  background: white;

  .card-header {
    @include flex-center;
    color: $primary-color;
    margin-bottom: $spacing / 2;
  }

  &:hover {
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  }
}
